parameters.code:
Script.Inputs = {
  JsonString: "string"
};

Script.Outputs = {
  Grid: "array",
  Done: "signal"
};

Script.Signals.Convert = function () {
  const raw = Script.Inputs.JsonString;
  let parsed;

  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    console.error("Invalid JSON", e);
    Script.Outputs.Grid = [];
    Script.Outputs.Done();
    return;
  }

  const gridMap = {};

  for (const key in parsed) {
    const value = parsed[key]; // e.g., "empty"
    const [yStr, xStr] = key.split(",");
    const x = parseInt(xStr);
    const y = parseInt(yStr);

    if (!gridMap[y]) {
      gridMap[y] = {
        y: y,
        cells: []
      };
    }

    gridMap[y].cells.push({
      x: x,
      stitch: value
    });
  }

  // Turn map into sorted array by row (y)
  const gridArray = Object.values(gridMap).sort((a, b) => a.y - b.y);
  Script.Outputs.Grid = gridArray;
  Script.Outputs.Done();
};

